        int maxn = 60;
        int[][][] dp = new int[maxn + 1][maxn + 1][shift * 2 + 1];
        for (int[][] layer : dp) {
            for (int[] row : layer) Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[maxn][maxn][shift] = 0;
        try {
            String s = in.readLine();
