                            if (plus + 1 <= maxn)
                                dp[plus][minus][carry] = Math.min(dp[plus][minus][carry], dp[plus + 1][minus][carry]);
                            if (minus + 1 <= maxn)
                                dp[plus][minus][carry] = Math.min(dp[plus][minus][carry], dp[plus][minus + 1][carry]);
                        }
                    }
                }
                int[][][] next = new int[maxn + 1][maxn + 1][shift * 2 + 1];
