                        }
                    }
                }
                dp = next;
            }
            int minCost = Integer.MAX_VALUE;
            for (int i = 0; i <= maxn; i++) {
                for (int j = 0; j <= maxn; j++) {
                    minCost = Math.min(minCost, dp[i][j][shift]);
                }
            }
            out.println(minCost);
