#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int shift = 15;
    int maxn = 60;
    vector<vector<vector<int>>> dp(maxn + 1, vector<vector<int>>(maxn + 1, vector<int>(shift * 2 + 1, INT_MAX)));
    dp[maxn][maxn][shift] = 0;
    string s;
    getline(cin, s);
    string d_str = "000" + s;
    vector<char> d(d_str.begin(), d_str.end());
    for (int i = (int)d.size() - 1; i >= 0; i--) {
        int digit = d[i] - '0';
        for (int plus = maxn; plus >= 0; plus--) {
            for (int minus = maxn; minus >= 0; minus--) {
                for (int carry = 0; carry <= 2 * shift; carry++) {
                    if (plus + 1 <= maxn)
                        dp[plus][minus][carry] = min(dp[plus][minus][carry], dp[plus + 1][minus][carry]);
                    if (minus + 1 <= maxn)
                        dp[plus][minus][carry] = min(dp[plus][minus][carry], dp[plus][minus + 1][carry]);
                }
            }
        }
        vector<vector<vector<int>>> next(maxn + 1, vector<vector<int>>(maxn + 1, vector<int>(shift * 2 + 1, INT_MAX)));
        for (int plus = maxn; plus >= 0; plus--) {
            for (int minus = maxn; minus >= 0; minus--) {
                for (int carry = 0; carry <= 2 * shift; carry++) {
                    int val = dp[plus][minus][carry];
                    if (val == INT_MAX) continue;
                    int realCarry = carry - shift;
                    int curN = plus - minus + realCarry;
                    int curD = curN % 10;
                    if (curD < 0) curD += 10;
                    int newCarry = (curN - curD) / 10;
                    if (curD != digit) continue;
                    int idx = newCarry + shift;
                    if (idx >= 0 && idx <= 2 * shift)
                        next[plus][minus][idx] = min(next[plus][minus][idx], plus + minus + val);
                }
            }
        }
        dp = move(next);
    }
    int minCost = INT_MAX;
    for (int i = 0; i <= maxn; i++) {
        for (int j = 0; j <= maxn; j++) {
            minCost = min(minCost, dp[i][j][shift]);
        }
    }
    cout << minCost << "\n";
    return 0;
}

